import{_ as r}from"./chunks/prontera-city.B6XwNokk.js";import{_ as o}from"./chunks/class-BnsurEbtsBwqzAd.BxBXo5Gb.js";import{_ as a}from"./chunks/prontera-street.BZRjh5Zm.js";import{_ as e,o as l,c as n,ag as i}from"./chunks/framework.DGzMGr_a.js";const q=JSON.parse('{"title":"启燃测试关服了，然后呢？——RO3接下来会怎么走","description":"启燃测试7月2日结束，巴哈上吵完了一轮。但测试关服之后，到底会发生什么？下一个测试什么时候？正式上线还远吗？聊聊我的判断。","frontmatter":{"title":"启燃测试关服了，然后呢？——RO3接下来会怎么走","date":"2026-07-04T00:00:00.000Z","description":"启燃测试7月2日结束，巴哈上吵完了一轮。但测试关服之后，到底会发生什么？下一个测试什么时候？正式上线还远吗？聊聊我的判断。"},"headers":[],"relativePath":"news/post-ignite-next-steps.md","filePath":"news/post-ignite-next-steps.md","lastUpdated":null}'),s={name:"news/post-ignite-next-steps.md"};function p(d,t,h,g,c,u){return l(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="启燃测试关服了-然后呢-——ro3接下来会怎么走" tabindex="-1">启燃测试关服了，然后呢？——RO3接下来会怎么走 <a class="header-anchor" href="#启燃测试关服了-然后呢-——ro3接下来会怎么走" aria-label="Permalink to &quot;启燃测试关服了，然后呢？——RO3接下来会怎么走&quot;">​</a></h1><blockquote><p>2026-07-04</p></blockquote><p>7月2号晚上十点，启燃测试正式关服。巴哈上安静了两天——吵完了，骂完了，该填的问卷也填了。但说实话，很多人心里还有一个问题没解决：</p><p><strong>然后呢？</strong></p><p>测试结束了，接下来会发生什么？下一次测试什么时候？正式上线还远不远？我把能收集到的信息整理一下，顺便聊聊我自己的判断。</p><p><img src="'+r+'" alt="RO3普隆德拉城"></p><p><img src="'+o+'" alt="RO3职业选择"></p><h2 id="先看时间线" tabindex="-1">先看时间线 <a class="header-anchor" href="#先看时间线" aria-label="Permalink to &quot;先看时间线&quot;">​</a></h2><p>根据目前已知的信息，RO3的计划大概是这样的：</p><table tabindex="0"><thead><tr><th>节点</th><th>时间</th><th>状态</th></tr></thead><tbody><tr><td>启燃测试</td><td>2026.06.25 - 07.02</td><td>已结束</td></tr><tr><td>测试报告/反馈总结</td><td>预计7月中旬</td><td>待公布</td></tr><tr><td>下一次测试</td><td>可能8-9月？</td><td>未确认</td></tr><tr><td>台港澳公测</td><td>2026下半年</td><td>官方说法</td></tr><tr><td>国服上线</td><td>2027年Q1</td><td>SEC文件披露</td></tr><tr><td>全球同步</td><td>2026下半年</td><td>官方说法</td></tr></tbody></table><p>这个时间线有几个关键点值得注意：</p><p><strong>第一，官方还没出测试报告。</strong> 启燃测试收集了大量反馈，按理说应该有一份总结——告诉玩家&quot;我们收到了什么反馈、会做什么调整&quot;。这份报告是最重要的风向标。如果报告里对玩家吐槽的宠物系统、疲劳值、精炼只字不提，那基本就是&quot;我们知道但不改&quot;。</p><p><strong>第二，下一次测试的时间不确定。</strong> 启燃测试是技术验证为主，不是内容测试。如果要验证商业化系统调整，可能还需要一次测试。但问题是——时间够吗？全球公测说是2026下半年，现在已经是7月了。</p><p><strong>第三，国服比台服晚半年。</strong> 这其实是好事。台服相当于替国服趟雷，出了问题还有时间改。</p><p><img src="'+a+'" alt="RO3普隆德拉街道"></p><h2 id="官方会怎么处理反馈" tabindex="-1">官方会怎么处理反馈 <a class="header-anchor" href="#官方会怎么处理反馈" aria-label="Permalink to &quot;官方会怎么处理反馈&quot;">​</a></h2><p>巴哈上玩家反馈的核心就四个字：<strong>太氪了</strong>。</p><p>抽卡宠物、氪金精炼、疲劳值、绑时间活动——这些问题制作人YU在直播里都听到了。但&quot;听到&quot;和&quot;改&quot;之间隔着一道墙。</p><p>我个人的判断是：<strong>宠物系统会调，但不会砍掉抽卡机制。</strong></p><p>原因很简单。RO3是Gravity和JoyMaker联合开发的，商业化模式不可能是制作人一个人说了算。抽卡宠物是收入来源，直接砍掉等于自断财路。更可能的做法是：</p><ol><li><strong>降低抽卡权重</strong>——比如UR宠物的获取概率提高，或者加入保底机制</li><li><strong>增加免费获取渠道</strong>——比如打副本也能掉宠物碎片</li><li><strong>削弱宠物的战力占比</strong>——让宠物更多是辅助，而不是核心输出</li></ol><p>至于疲劳值，这个改动的可能性最大。因为疲劳值的设计初衷是防外挂，但实际效果是限制了正常玩家。完全可以用其他方式防外挂（比如行为检测、设备指纹），没必要让所有人为外挂买单。</p><p>精炼系统比较复杂。RO1的精炼是随机失败但材料便宜，RO3的精炼是需要氪金材料。如果能把氪金材料改成副本掉落，问题就解决了一大半。</p><h2 id="对普通玩家意味着什么" tabindex="-1">对普通玩家意味着什么 <a class="header-anchor" href="#对普通玩家意味着什么" aria-label="Permalink to &quot;对普通玩家意味着什么&quot;">​</a></h2><p>如果你是<strong>等国服的玩家</strong>，其实可以更乐观一点。</p><p>国服2027年Q1上线，比台服晚半年。这意味着：</p><ul><li>台服公测后暴露的问题，国服有机会看到并调整</li><li>如果台服口碑不好，国服可能会重新评估上线时间</li><li>你有充足的时间观望，不用着急</li></ul><p>如果你是<strong>打算台服公测就玩的玩家</strong>，建议先别冲太多钱。公测第一个月是最混乱的——系统不稳定、经济体系没成型、平衡性可能大改。等一两个月再决定要不要认真玩。</p><p>如果你是<strong>纯粹好奇的玩家</strong>，可以关注这几个信息源：</p><ul><li>巴哈姆特RO3版（台港澳玩家最活跃的地方）</li><li>官方Facebook（<a href="https://www.facebook.com/RagnarokOnline3tc/" target="_blank" rel="noreferrer">RO仙境傳說3</a>）</li><li>官方Discord（<a href="https://discord.gg/ro3global" target="_blank" rel="noreferrer">ro3global</a>）</li><li>本站的新闻更新（我会持续跟踪）</li></ul><h2 id="我的判断" tabindex="-1">我的判断 <a class="header-anchor" href="#我的判断" aria-label="Permalink to &quot;我的判断&quot;">​</a></h2><p>启燃测试最大的收获不是&quot;游戏好不好玩&quot;——这个问题其实已经回答了，底子不差。最大的收获是<strong>开发团队终于知道了玩家在气什么</strong>。</p><p>问题是：他们愿不愿意改。</p><p>RO系列出过太多手游了。从RO1到RO手游、RO守护永恒的爱、RO爱如初见……每一款上线前都说&quot;我们会听取玩家意见&quot;，每一款上线后都是一样的套路——月卡、抽卡、氪金变强。</p><p>RO3如果还是这条路，那就是又一款&quot;出了一年就凉&quot;的RO手游。</p><p>但如果它能真的改——哪怕只是把宠物抽卡改成月卡制，把精炼材料改成副本掉落——都能成为近几年最好的RO续作。</p><p>就看接下来两个月官方怎么说了。</p><h2 id="值得关注的几个时间点" tabindex="-1">值得关注的几个时间点 <a class="header-anchor" href="#值得关注的几个时间点" aria-label="Permalink to &quot;值得关注的几个时间点&quot;">​</a></h2><ul><li><strong>7月中旬</strong>：官方测试报告（如果有的话）</li><li><strong>8月</strong>：是否宣布下一次测试</li><li><strong>9-10月</strong>：台港澳公测时间确认</li><li><strong>2027年Q1</strong>：国服上线</li></ul><p>我会持续跟踪这些节点，有新消息第一时间更新。</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li><a href="https://forum.gamer.com.tw/B.php?bsn=81475" target="_blank" rel="noreferrer">巴哈姆特：RO3 哈啦板</a></li><li><a href="https://ro3global.com/zh-TW/" target="_blank" rel="noreferrer">RO3官网</a></li><li><a href="https://www.facebook.com/RagnarokOnline3tc/" target="_blank" rel="noreferrer">官方Facebook：RO仙境傳說3</a></li><li><a href="https://gnn.gamer.com.tw/detail.php?sn=306111" target="_blank" rel="noreferrer">GNN：启燃测试开放招募</a></li></ul>',42)])])}const R=e(s,[["render",p]]);export{q as __pageData,R as default};
